// Guards: UI map and screen help (CLAUDE.md, Platform Admin 16 Nov 2026 09:04): docs/UI-MAP.md is generated by scripts/ui-map.mjs from the menu, the page switch and the screen components, and a PR that moves, renames or folds UI controls regenerates it in the same release
// CF-247 S557. The generator reads src/nav-map.js (PAGES, SECTIONS, LEGACY), pageBody in src/mature-main.jsx and each screen's component source.
// The release line of the document is not compared, so a change that touches no screen structure never fails here.
import { test, expect } from '@playwright/test'
import fs from 'node:fs'
import { build, structureOnly } from '../../scripts/ui-map.mjs'
import { PAGES, SECTIONS, hrefFor } from '../../src/nav-map.js'

const made = build()

test('the generator maps every menu page and tab to a screen and stops rather than guess', () => {
  expect(made.problems, 'ui-map problems').toEqual([])
  expect(made.count.pages).toBe(Object.keys(PAGES).length)
  expect(SECTIONS.flatMap((s) => s.pages).sort()).toEqual(Object.keys(PAGES).sort())
  for (const p of Object.values(PAGES)) {
    expect(made.text, p.label).toContain(`### ${p.label} — \`#${p.slug}\``)
    for (const t of p.tabs || []) expect(made.text, `${p.label} › ${t.label}`).toContain(`#### ${p.label} › ${t.label} — \`${hrefFor(p.key, t.key)}\``)
  }
  expect(made.text).not.toContain('**Screen:** none found')
})

test('docs/UI-MAP.md is what the source gives now: a screen change regenerates it in the same change (node scripts/ui-map.mjs)', () => {
  expect(fs.existsSync('docs/UI-MAP.md'), 'docs/UI-MAP.md is missing: run node scripts/ui-map.mjs').toBe(true)
  const have = fs.readFileSync('docs/UI-MAP.md', 'utf8')
  expect(structureOnly(have) === structureOnly(made.text), 'docs/UI-MAP.md is behind the screens: run node scripts/ui-map.mjs and commit it with the screen help text').toBe(true)
  expect(have).toMatch(/^<!-- ui-map: release \d+\.\d+\.\d+ -->$/m)
})

test('the rule is written where every session reads it', () => {
  const rules = fs.readFileSync('CLAUDE.md', 'utf8')
  expect(rules).toContain('UI map and screen help')
  expect(rules).toContain('node scripts/ui-map.mjs')
  expect(rules).toContain('inline screen help text')
})
